"use client"

import { useState, useEffect } from "react"
import { Calendar, Clock, Thermometer, CloudRain, Wind, Droplets, AlertTriangle, TrendingUp } from "lucide-react"
import DatePicker from "react-datepicker"
import { format, subDays } from "date-fns"
import { es } from "date-fns/locale"
import { fetchProductos } from "../services/api"
import ZoomableImage from "./ZoomableImage"
import "react-datepicker/dist/react-datepicker.css"

const WRFSection = ({ loading: initialLoading }) => {
  const [selectedDate, setSelectedDate] = useState(new Date())
  const [selectedTime, setSelectedTime] = useState("12:00")
  const [selectedVariable, setSelectedVariable] = useState("t2")
  const [productos, setProductos] = useState([])
  const [loading, setLoading] = useState(initialLoading)
  const [currentImage, setCurrentImage] = useState(null)

  const variables = [
    {
      id: "t2",
      name: "Temperatura a 2m",
      icon: Thermometer,
      color: "text-orange-600",
      bgColor: "bg-orange-50",
      borderColor: "border-orange-200",
      description: "Temperatura del aire a 2 metros sobre el suelo (°C)",
    },
    {
      id: "ppn",
      name: "Precipitación",
      icon: CloudRain,
      color: "text-blue-600",
      bgColor: "bg-blue-50",
      borderColor: "border-blue-200",
      description: "Tasa instantánea de precipitación (mm/h)",
    },
    {
      id: "wspd10",
      name: "Velocidad Viento",
      icon: Wind,
      color: "text-green-600",
      bgColor: "bg-green-50",
      borderColor: "border-green-200",
      description: "Velocidad del viento (m/s) a 10 m de altura",
    },
    {
      id: "wdir10",
      name: "Dirección Viento",
      icon: Wind,
      color: "text-green-600",
      bgColor: "bg-green-50",
      borderColor: "border-green-200",
      description: "Dirección desde donde sopla el viento (°)",
    },
    {
      id: "rh2",
      name: "Humedad Relativa",
      icon: Droplets,
      color: "text-purple-600",
      bgColor: "bg-purple-50",
      borderColor: "border-purple-200",
      description: "Porcentaje de humedad relativa a 2 metros",
    },
    {
      id: "dbz_altura",
      name: "Reflectividad",
      icon: TrendingUp,
      color: "text-yellow-600",
      bgColor: "bg-yellow-50",
      borderColor: "border-yellow-200",
      description: "Simulación de reflectividad radar (dBZ)",
    },
    {
      id: "riesgos_vientos",
      name: "Riesgo Vientos",
      icon: AlertTriangle,
      color: "text-red-600",
      bgColor: "bg-red-50",
      borderColor: "border-red-200",
      description: "Áreas con riesgo de viento fuerte",
    },
    {
      id: "ppnaccum",
      name: "Precipitación Acumulada",
      icon: CloudRain,
      color: "text-blue-600",
      bgColor: "bg-blue-50",
      borderColor: "border-blue-200",
      description: "Acumulado total de precipitación (mm)",
    },
  ]

  const timeSlots = Array.from({ length: 25 }, (_, i) => {
    const hour = i.toString().padStart(2, "0")
    return `${hour}:00`
  })

  useEffect(() => {
    loadWRFData()
  }, [selectedDate, selectedTime, selectedVariable])

  const loadWRFData = async () => {
    try {
      setLoading(true)
      const dateStr = format(selectedDate, "yyyy-MM-dd")
      const response = await fetchProductos({
        tipo: "wrf_cba",
        fecha: dateStr,
        variable: selectedVariable,
      })

      const productosData = response.results || response
      setProductos(productosData)

      // Buscar imagen para la hora seleccionada
      const matchingProduct = productosData.find(
        (p) =>
          p.nombre_archivo.includes(`_${selectedTime.replace(":", "")}+`) ||
          p.nombre_archivo.includes(`+${selectedTime.replace(":", "")}`),
      )

      setCurrentImage(matchingProduct?.url_imagen || null)
    } catch (error) {
      console.error("Error loading WRF data:", error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div style={{background: '#171F2F99', borderRadius: '1.5rem', boxShadow: '0 4px 24px 0 rgba(23,31,47,0.10)'}} className="p-6">
        <div className="flex items-center space-x-3 mb-2">
          <h2 className="text-2xl font-bold text-white flex items-center">
            <span className="bg-blue-600 p-2 rounded-lg mr-2 flex items-center justify-center">
              <Thermometer className="h-6 w-6 text-white" />
            </span>
            Modelo WRF - Córdoba
          </h2>
        </div>
        <p className="text-gray-200">
          Productos horarios del modelo meteorológico WRF para Córdoba. Actualizaciones diarias a las 06 y 18 UTC.
        </p>
      </div>

      {/* Date Selector */}
      <div style={{background: '#171F2F99', borderRadius: '1.5rem', boxShadow: '0 4px 24px 0 rgba(23,31,47,0.10)'}} className="p-6">
        <div className="flex items-center space-x-3 mb-4">
          <Calendar className="h-5 w-5 text-white" />
          <h3 className="text-lg font-semibold text-white">Seleccionar fecha</h3>
        </div>

        <div className="grid md:grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-medium text-white mb-2">Fecha</label>
            <DatePicker
              selected={selectedDate}
              onChange={setSelectedDate}
              dateFormat="dd/MM/yyyy"
              locale={es}
              maxDate={new Date()}
              minDate={subDays(new Date(), 30)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-white mb-2">Fecha seleccionada</label>
            <div className="bg-blue-50 border border-blue-200 p-3 rounded-lg">
              <span className="font-semibold text-blue-800">{format(selectedDate, "dd/MM/yyyy", { locale: es })}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Variable Selection */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {variables.map((variable) => {
          const Icon = variable.icon
          const isSelected = selectedVariable === variable.id

          return (
            <button
              key={variable.id}
              onClick={() => setSelectedVariable(variable.id)}
              style={{background: '#171F2F99', borderRadius: '1.5rem', boxShadow: '0 4px 24px 0 rgba(23,31,47,0.10)'}}
              className={`text-left w-full p-4 border-2 transition-all duration-200 ${isSelected ? `${variable.borderColor}` : 'border-transparent'}`}
            >
              <div className="flex items-center gap-3">
                <span className={`w-12 h-12 rounded-lg flex items-center justify-center ${variable.bgColor} border ${variable.borderColor}`}>
                  <Icon className={`h-6 w-6 ${variable.color}`} />
                </span>
                <div>
                  <h3 className="font-semibold text-white mb-1">{variable.name}</h3>
                  <p className="text-sm text-gray-200">{variable.description}</p>
                </div>
              </div>
            </button>
          )
        })}
      </div>

      {/* Time Selection */}
      <div style={{background: '#171F2F99', borderRadius: '1.5rem', boxShadow: '0 4px 24px 0 rgba(23,31,47,0.10)'}} className="p-6">
        <div className="flex items-center space-x-3 mb-4">
          <Clock className="h-5 w-5 text-blue-600" />
          <h3 className="text-lg font-semibold text-white">Hora de Pronóstico (ARG)</h3>
        </div>

        <div className="grid grid-cols-5 md:grid-cols-10 gap-2 justify-center text-center">
          {timeSlots.map((time) => (
            <button
              key={time}
              onClick={() => setSelectedTime(time)}
              className={
                `time-button flex items-center justify-center ${selectedTime === time ? "time-button-active" : "time-button-inactive"}`
              }
            >
              {time}
            </button>
          ))}
        </div>
      </div>

      {/* Image Display */}
      <div style={{background: '#171F2F99', borderRadius: '1.5rem', boxShadow: '0 4px 24px 0 rgba(23,31,47,0.10)'}} className="p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-white">
            {variables.find((v) => v.id === selectedVariable)?.name}
          </h3>
          <span className="text-sm text-gray-500 bg-gray-100 px-3 py-1 rounded-full">{selectedTime} ARG</span>
        </div>

        {loading ? (
          <div className="flex items-center justify-center h-96 bg-gray-50 rounded-lg">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
          </div>
        ) : currentImage ? (
          <ZoomableImage
            src={currentImage}
            alt={`${selectedVariable} - ${format(selectedDate, "dd/MM/yyyy")} ${selectedTime}`}
            className="w-full"
          />
        ) : (
          <div className="flex items-center justify-center h-96 bg-gray-50 rounded-lg border-2 border-dashed border-gray-300">
            <div className="text-center">
              <AlertTriangle className="h-12 w-12 text-gray-400 mx-auto mb-2" />
              <p className="text-gray-500">No hay datos disponibles para la fecha y hora seleccionadas</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default WRFSection
